#pragma once

#include "exchange/core/trade.hpp"
#include "exchange/core/types.hpp"

#include <string>
#include <vector>

namespace exchange {

// Request used to submit an order into the engine. Order ids are generated by
// the engine; clients do not supply them.
struct OrderRequest {
    AccountID account_id = 0;
    std::string symbol;
    Side side = Side::Buy;
    OrderType type = OrderType::Limit;
    Price price = 0;
    Quantity quantity = 0;
    TimeInForce tif = TimeInForce::GTC;
};

// Result of a place-order call. `reason` explains a rejection or why the
// remainder of an immediately-executed order was not rested; it is empty for a
// fully executed order.
struct PlaceResult {
    bool accepted = false;
    std::string reason;
    OrderID order_id = 0;
    OrderStatus status = OrderStatus::New;
    Price average_price = 0;
    Quantity executed = 0;
    Quantity leaves = 0;
    std::vector<Trade> trades;
};

} // namespace exchange
